        this.hat = (AnimatedGeoBone)bones.get((Object)"Hat");
        this.leftArm = (AnimatedGeoBone)bones.get((Object)"LeftArm");
        this.rightArm = (AnimatedGeoBone)bones.get((Object)"RightArm");
